-- Neat: pagos B2C, no gestión financiera.
insert into public.aml_fintech_profile_audit(fintech_id,classifier_version,business_model,business_model_confidence,target_customer,target_customer_confidence,revenue_model,revenue_model_confidence,pages_scanned,observed_at,evidence)
select fintech_id,'MANUAL_VERTICAL_CORRECTION_NEAT_2026_09_09','B2C',0.999,'PERSONAS',0.999,revenue_model,revenue_model_confidence,2,now(),jsonb_build_object('old_primary_vertical',primary_vertical,'new_primary_vertical','Procesamiento de pagos y remesas','source_url','https://www.neatpagos.com/','manual_validation',true)
from public.aml_fintech_entity where fintech_id='ENT-RUT-77005598-9'
and not exists(select 1 from public.aml_fintech_profile_audit where fintech_id='ENT-RUT-77005598-9' and classifier_version='MANUAL_VERTICAL_CORRECTION_NEAT_2026_09_09');
update public.aml_fintech_entity set primary_vertical='Procesamiento de pagos y remesas',business_model='B2C',target_customer='PERSONAS',business_model_basis='Plataforma de pagos de cuentas orientada a personas.',business_model_confidence=0.999,target_customer_basis='La portada y centro de ayuda describen flujos de pago para usuarios finales.',target_customer_confidence=0.999,profile_classifier_version='MANUAL_VERTICAL_CORRECTION_NEAT_2026_09_09',profile_refreshed_at=now(),refreshed_at=now() where fintech_id='ENT-RUT-77005598-9';
insert into public.aml_fintech_function_observation(observation_key,subject_type,subject_key,function_code,evidence_status,evidence_class,confidence,basis,source_code,source_url,evidence_excerpt,first_seen_at,last_seen_at,observed_at)
values('OFFICIAL|NEAT|FIN_PAYMENTS|2026-09-09','ENTITY','ENT-RUT-77005598-9','FIN_PAYMENTS','OBSERVED','OFFICIAL_OPEN',1.0,'Neat permite pagar cuentas con tarjetas, pagos programados, pagos automáticos y transferencias bancarias.','COMPANY_OFFICIAL','https://ayuda.neatpagos.com/es/articles/7135931-que-modalidades-de-pagos-tiene-neat-existen-pagos-automaticos','Pagos manuales, automáticos, transferencias bancarias y saldos precargados.',now(),now(),now())
on conflict(observation_key) do update set evidence_status=excluded.evidence_status,evidence_class=excluded.evidence_class,confidence=excluded.confidence,basis=excluded.basis,source_code=excluded.source_code,source_url=excluded.source_url,evidence_excerpt=excluded.evidence_excerpt,last_seen_at=now(),observed_at=excluded.observed_at;
insert into public.aml_fintech_market_metric_observation(observation_key,subject_type,subject_key,metric_code,value_numeric,value_text,unit,qualifier,geography,evidence_type,confidence,source_code,source_url,observed_at,basis,metadata,first_seen_at,last_seen_at)
values('COMPANY_OFFICIAL|NEAT|USERS|2026-09-09','ENTITY','ENT-RUT-77005598-9','USERS',230000,'Más de 230.000 personas usan Neat','users','AT_LEAST','CHILE','DECLARADO',0.999,'COMPANY_OFFICIAL','https://www.neatpagos.com/',now(),'Piso de alcance B2C; no equivale a usuarios activos mensuales.',jsonb_build_object('lower_bound',true,'not_monthly_active_users',true),now(),now())
on conflict(observation_key) do update set value_numeric=excluded.value_numeric,value_text=excluded.value_text,observed_at=excluded.observed_at,basis=excluded.basis,metadata=excluded.metadata,last_seen_at=now();

